The class template scoped_allocator_adaptor is an allocator template that specifies an allocator resource (the outer allocator) to be used by a container (as any other allocator does) and also specifies an inner allocator resource to be passed to the constructor of every element within the container. This adaptor is instantiated with one outer and zero or more inner allocator types. If instantiated with only one allocator type, the inner allocator becomes the scoped_allocator_adaptor itself, thus using the same allocator resource for the container and every element within the container and, if the elements themselves are containers, each of their elements recursively. If instantiated with more than one allocator, the first allocator is the outer allocator for use by the container, the second allocator is passed to the constructors of the container's elements, and, if the elements themselves are containers, the third allocator is passed to the elements' elements, and so on. If containers are nested to a depth greater than the number of allocators, the last allocator is used repeatedly, as in the single-allocator case, for any remaining recursions. [Note 1: The scoped_allocator_adaptor is derived from the outer allocator type so it can be substituted for the outer allocator type in most expressions. — end note]

namespace std {
 template<class OuterAlloc, class... InnerAllocs>
 class scoped_allocator_adaptor : public OuterAlloc {
 private:
 using OuterTraits = allocator_traits<OuterAlloc>; // exposition only
 scoped_allocator_adaptor<InnerAllocs...> inner; // exposition only
 public:
 using outer_allocator_type = OuterAlloc;
 using inner_allocator_type = see below;
 using value_type = typename OuterTraits::value_type;
 using size_type = typename OuterTraits::size_type;
 using difference_type = typename OuterTraits::difference_type;
 using pointer = typename OuterTraits::pointer;
 using const_pointer = typename OuterTraits::const_pointer;
 using void_pointer = typename OuterTraits::void_pointer;
 using const_void_pointer = typename OuterTraits::const_void_pointer;
 using propagate_on_container_copy_assignment = see below;
 using propagate_on_container_move_assignment = see below;
 using propagate_on_container_swap = see below;
 using is_always_equal = see below;
 template<class Tp> struct rebind {
 using other = scoped_allocator_adaptor<
 OuterTraits::template rebind_alloc<Tp>, InnerAllocs...>;
 };
 scoped_allocator_adaptor();
 template<class OuterA2>
 scoped_allocator_adaptor(OuterA2&& outerAlloc,
 const InnerAllocs&... innerAllocs) noexcept;
 scoped_allocator_adaptor(const scoped_allocator_adaptor& other) noexcept;
 scoped_allocator_adaptor(scoped_allocator_adaptor&& other) noexcept;
 template<class OuterA2>
