In every specialization basic_string_view<charT, traits>, the type traits shall meet the character traits requirements ([char.traits]). [Note 1: The program is ill-formed if traits:: char_type is not the same type as charT. — end note]

template<class It, class End>
 constexpr basic_string_view(It begin, End end);

Constraints: It satisfies contiguous_iterator. End satisfies sized_sentinel_for<It>. is_same_v<iter_value_t<It>, charT> is true. is_convertible_v<End, size_type> is false.

template<class It, class End>
 constexpr basic_string_view(It begin, End end);

Preconditions: [begin, end) is a valid range. It models contiguous_iterator. End models sized_sentinel_for<It>.

template<class It, class End>
 constexpr basic_string_view(It begin, End end);

Effects: Initializes data_ with to_address(begin) and initializes size_ with end - begin.

template<class It, class End>
 constexpr basic_string_view(It begin, End end);

Throws: When and what end - begin throws.

template<class R>
 constexpr explicit basic_string_view(R&& r);

Let d be an lvalue of type remove_cvref_t<R>.

template<class R>
 constexpr explicit basic_string_view(R&& r);

Constraints: remove_cvref_t<R> is not the same type as basic_string_view, R models ranges:: contiguous_range and ranges:: sized_range, is_same_v<ranges:: range_value_t<R>, charT> is true, is_convertible_v<R, const charT*> is false, and d.operator:: std:: basic_string_view<charT, traits>() is not a valid expression.

template<class R>
 constexpr explicit basic_string_view(R&& r);

Effects: Initializes data_ with ranges:: data(r) and size_ with ranges:: size(r).

template<class R>
 constexpr explicit basic_string_view(R&& r);

Throws: Any exception thrown by ranges:: data(r) and ranges:: size(r).

template<class It, class End>
 basic_string_view(It, End) -> basic_string_view<iter_value_t<It>>;

Constraints: It satisfies contiguous_iterator. End satisfies sized_sentinel_for<It>.

template<class R>
 basic_string_view(R&&) -> basic_string_view<ranges::range_value_t<R>>;

Constraints: R satisfies ranges:: contiguous_range.

constexpr const_iterator begin() const noexcept;
constexpr const_iterator cbegin() const noexcept;

Returns: An iterator such that if !empty(), addressof(*begin()) == data_, otherwise, an unspecified value such that [begin(), end()) is a valid range.

constexpr const_iterator end() const noexcept;
constexpr const_iterator cend() const noexcept;

Returns: begin() + size().

constexpr const_reverse_iterator rbegin() const noexcept;
constexpr const_reverse_iterator crbegin() const noexcept;

Returns: const_reverse_iterator(end()).

constexpr const_reverse_iterator rend() const noexcept;
constexpr const_reverse_iterator crend() const noexcept;

Returns: const_reverse_iterator(begin()).

constexpr size_type size() const noexcept;
constexpr size_type length() const noexcept;

Returns: size_.

constexpr size_type max_size() const noexcept;

Returns: The largest possible number of char-like objects that can be referred to by a basic_string_view.

[[nodiscard]] constexpr bool empty() const noexcept;

Returns: size_ == 0.

constexpr int compare(size_type pos1, size_type n1, basic_string_view str,
 size_type pos2, size_type n2) const;

Effects: Equivalent to: return substr(pos1, n1).compare(str.substr(pos2, n2));

constexpr bool ends_with(basic_string_view x) const noexcept;

Effects: Equivalent to:

return size() >= x.size() && compare(size() - x.size(), npos, x) == 0;

constexpr bool contains(basic_string_view x) const noexcept;
constexpr bool contains(charT x) const noexcept;
constexpr bool contains(const charT* x) const;

Effects: Equivalent to: return find(x) != npos;

