template<class M>
concept layout-mapping-alike = requires { // exposition only
 requires is-extents<typename M::extents_type>;
 { M::is_always_strided() } -> same_as<bool>;
 { M::is_always_exhaustive() } -> same_as<bool>;
 { M::is_always_unique() } -> same_as<bool>;
 bool_constant<M::is_always_strided()>::value;
 bool_constant<M::is_always_exhaustive()>::value;
 bool_constant<M::is_always_unique()>::value;
};

[Note 1: This concept checks that the functions M:: is_always_strided(), M:: is_always_exhaustive(), and M:: is_always_unique() exist, are constant expressions, and have a return type of bool. — end note]

