template<class T>
 requires is_object_v<T>
struct cond-value-type<T> {
 using value_type = remove_cv_t<T>;
};
template<class T>
 concept has-member-value-type = requires { typename T::value_type; }; // exposition only
template<class T>
 concept has-member-element-type = requires { typename T::element_type; }; // exposition only
template<class> struct indirectly_readable_traits { };
template<class T>
struct indirectly_readable_traits<T*>
 : cond-value-type<T> { };
template<class I>
 requires is_array_v<I>
struct indirectly_readable_traits<I> {
 using value_type = remove_cv_t<remove_extent_t<I>>;
};
template<class I>
struct indirectly_readable_traits<const I>
 : indirectly_readable_traits<I> { };
template<has-member-value-type T>
struct indirectly_readable_traits<T>
 : cond-value-type<typename T::value_type> { };
template<has-member-element-type T>
struct indirectly_readable_traits<T>
 : cond-value-type<typename T::element_type> { };
template<has-member-value-type T>
 requires has-member-element-type<T>
struct indirectly_readable_traits<T> { };
template<has-member-value-type T>
 requires has-member-element-type<T> &&
 same_as<remove_cv_t<typename T::element_type>, remove_cv_t<typename T::value_type>>
struct indirectly_readable_traits<T>
 : cond-value-type<typename T::value_type> { };
template<class T> using iter_value_t = see below;

The definitions in this subclause make use of the following exposition-only concepts:

template<class I>
concept cpp17-iterator =
 requires(I i) {
 { *i } -> can-reference;
 { ++i } -> same_as<I&>;
 { *i++ } -> can-reference;
 } && copyable<I>;
template<class I>
concept cpp17-input-iterator =
 cpp17-iterator<I> && equality_comparable<I> && requires(I i) {
 typename incrementable_traits<I>::difference_type;
 typename indirectly_readable_traits<I>::value_type;
 typename common_reference_t<iter_reference_t<I>&&,
 typename indirectly_readable_traits<I>::value_type&>;
 typename common_reference_t<decltype(*i++)&&,
 typename indirectly_readable_traits<I>::value_type&>;
 requires signed_integral<typename incrementable_traits<I>::difference_type>;
 };
template<class I>
concept cpp17-forward-iterator =
 cpp17-input-iterator<I> && constructible_from<I> &&
 is_reference_v<iter_reference_t<I>> &&
 same_as<remove_cvref_t<iter_reference_t<I>>,
 typename indirectly_readable_traits<I>::value_type> &&
 requires(I i) {
 { i++ } -> convertible_to<const I&>;
 { *i++ } -> same_as<iter_reference_t<I>>;
 };
template<class I>
concept cpp17-bidirectional-iterator =
 cpp17-forward-iterator<I> && requires(I i) {
 { --i } -> same_as<I&>;
 { i-- } -> convertible_to<const I&>;
 { *i-- } -> same_as<iter_reference_t<I>>;
 };
template<class I>
concept cpp17-random-access-iterator =
 cpp17-bidirectional-iterator<I> && totally_ordered<I> &&
 requires(I i, typename incrementable_traits<I>::difference_type n) {
 { i += n } -> same_as<I&>;
 { i -= n } -> same_as<I&>;
 { i + n } -> same_as<I>;
 { n + i } -> same_as<I>;
 { i - n } -> same_as<I>;
 { i - i } -> same_as<decltype(n)>;
 { i[n] } -> convertible_to<iter_reference_t<I>>;
 };

The members of a specialization iterator_traits<I> generated from the iterator_traits primary template are computed as follows: If I has valid ([temp.deduct]) member types difference_type, value_type, reference, and iterator_category, then iterator_traits<I> has the following publicly accessible members:

using iterator_category = typename I::iterator_category;
using value_type = typename I::value_type;
using difference_type = typename I::difference_type;
using pointer = see below;
using reference = typename I::reference;

If the qualified-id I:: pointer is valid and denotes a type, then iterator_traits<I>:: pointer names that type; otherwise, it names void. Otherwise, if I satisfies the exposition-only concept cpp17-input-iterator, iterator_traits<I> has the following publicly accessible members:

using iterator_category = see below;
using value_type = typename indirectly_readable_traits<I>::value_type;
using difference_type = typename incrementable_traits<I>::difference_type;
using pointer = see below;
using reference = see below;

If the qualified-id I:: pointer is valid and denotes a type, pointer names that type. Otherwise, if decltype(declval<I&>().operator->()) is well-formed, then pointer names that type. Otherwise, pointer names void. If the qualified-id I:: reference is valid and denotes a type, reference names that type. Otherwise, reference names iter_reference_t<I>. If the qualified-id I:: iterator_category is valid and denotes a type, iterator_category names that type. Otherwise, iterator_category names: random_access_iterator_tag if I satisfies cpp17-random-access-iterator, or otherwise bidirectional_iterator_tag if I satisfies cpp17-bidirectional-iterator, or otherwise forward_iterator_tag if I satisfies cpp17-forward-iterator, or otherwise input_iterator_tag. Otherwise, if I satisfies the exposition-only concept cpp17-iterator, then iterator_traits<I> has the following publicly accessible members:

using iterator_category = output_iterator_tag;
using value_type = void;
using difference_type = see below;
using pointer = void;
using reference = void;

If the qualified-id incrementable_traits<I>:: difference_type is valid and denotes a type, then difference_type names that type; otherwise, it names void. Otherwise, iterator_traits<I> has no members by any of the above names.

iterator_traits is specialized for pointers as

namespace std {
 template<class T>
 requires is_object_v<T>
 struct iterator_traits<T*> {
 using iterator_concept = contiguous_iterator_tag;
 using iterator_category = random_access_iterator_tag;
 using value_type = remove_cv_t<T>;
 using difference_type = ptrdiff_t;
 using pointer = T*;
 using reference = T&;
 };
}

[Example 2: To implement a generic reverse function, a C++ program can do the following:

template<class BI>
void reverse(BI first, BI last) {
 typename iterator_traits<BI>::difference_type n =
 distance(first, last);
 --n;
 while(n > 0) {
 typename iterator_traits<BI>::value_type
 tmp = *first;
 *first++ = *--last;
 *last = tmp;
 n -= 2;
 }
}

— end example]

template<class X, class Y>
 constexpr iter_value_t<X> iter-exchange-move(X&& x, Y&& y)
 noexcept(noexcept(iter_value_t<X>(iter_move(x))) &&
 noexcept(*x = iter_move(y)));

Effects: Equivalent to:

iter_value_t<X> old_value(iter_move(x));
*x = iter_move(y);
return old_value;

For a type I, let ITER_TRAITS(I) denote the type I if iterator_traits<I> names a specialization generated from the primary template. Otherwise, ITER_TRAITS(I) denotes iterator_traits<I>. If the qualified-id ITER_TRAITS(I):: iterator_concept is valid and names a type, then ITER_CONCEPT(I) denotes that type. Otherwise, if the qualified-id ITER_TRAITS(I):: iterator_category is valid and names a type, then ITER_CONCEPT(I) denotes that type. Otherwise, if iterator_traits<I> names a specialization generated from the primary template, then ITER_CONCEPT(I) denotes random_access_iterator_tag. Otherwise, ITER_CONCEPT(I) does not denote a type.

[Note 1: ITER_TRAITS enables independent syntactic determination of an iterator's category and concept. — end note] [Example 1:

struct I {
 using value_type = int;
 using difference_type = int;
 int operator*() const;
 I& operator++();
 I operator++(int);
 I& operator--();
 I operator--(int);
 bool operator==(I) const;
};

iterator_traits<I>:: iterator_category denotes input_iterator_tag, and ITER_CONCEPT(I) denotes random_access_iterator_tag. — end example]

Types that are indirectly readable by applying operator* model the indirectly_readable concept, including pointers, smart pointers, and iterators.

template<class In>
 concept indirectly-readable-impl =
 requires(const In in) {
 typename iter_value_t<In>;
 typename iter_reference_t<In>;
 typename iter_rvalue_reference_t<In>;
 { *in } -> same_as<iter_reference_t<In>>;
 { ranges::iter_move(in) } -> same_as<iter_rvalue_reference_t<In>>;
 } &&
 common_reference_with<iter_reference_t<In>&&, iter_value_t<In>&> &&
 common_reference_with<iter_reference_t<In>&&, iter_rvalue_reference_t<In>&&> &&
 common_reference_with<iter_rvalue_reference_t<In>&&, const iter_value_t<In>&>;

template<class In>
 concept indirectly_readable =
 indirectly-readable-impl<remove_cvref_t<In>>;

Given a value i of type I, I models indirectly_readable only if the expression *i is equality-preserving.

The weakly_incrementable concept specifies the requirements on types that can be incremented with the pre- and post-increment operators. The increment operations are not required to be equality-preserving, nor is the type required to be equality_comparable.

template<class T>
 constexpr bool is-integer-like = see below; // exposition only
template<class T>
 constexpr bool is-signed-integer-like = see below; // exposition only
template<class I>
 concept weakly_incrementable =
 movable<I> &&
 requires(I i) {
 typename iter_difference_t<I>;
 requires is-signed-integer-like<iter_difference_t<I>>;
 { ++i } -> same_as<I&>; // not required to be equality-preserving
 i++; // not required to be equality-preserving
 };

The incrementable concept specifies requirements on types that can be incremented with the pre- and post-increment operators. The increment operations are required to be equality-preserving, and the type is required to be equality_comparable. [Note 1: This supersedes the annotations on the increment expressions in the definition of weakly_incrementable. — end note]

template<class I>
 concept incrementable =
 regular<I> &&
 weakly_incrementable<I> &&
 requires(I i) {
 { i++ } -> same_as<I>;
 };

Let a and b be incrementable objects of type I. I models incrementable only if If bool(a == b) then bool(a++ == b). If bool(a == b) then bool(((void)a++, a) == ++b).

[Note 2: The requirement that a equals b implies ++a equals ++b (which is not true for weakly incrementable types) allows the use of multi-pass one-directional algorithms with types that model incrementable. — end note]

The input_or_output_iterator concept forms the basis of the iterator concept taxonomy; every iterator models input_or_output_iterator. This concept specifies operations for dereferencing and incrementing an iterator. Most algorithms will require additional operations to compare iterators with sentinels ([iterator.concept.sentinel]), to read ([iterator.concept.input]) or write ([iterator.concept.output]) values, or to provide a richer set of iterator movements ([iterator.concept.forward], [iterator.concept.bidir], [iterator.concept.random.access]).

template<class I>
 concept input_or_output_iterator =
 requires(I i) {
 { *i } -> can-reference;
 } &&
 weakly_incrementable<I>;

[Note 1: Unlike the Cpp17Iterator requirements, the input_or_output_iterator concept does not require copyability. — end note]

template<class S, class I>
 concept sized_sentinel_for =
 sentinel_for<S, I> &&
 !disable_sized_sentinel_for<remove_cv_t<S>, remove_cv_t<I>> &&
 requires(const I& i, const S& s) {
 { s - i } -> same_as<iter_difference_t<I>>;
 { i - s } -> same_as<iter_difference_t<I>>;
 };

Let i be an iterator of type I, and s a sentinel of type S such that [i, s) denotes a range. Let N be the smallest number of applications of ++i necessary to make bool(i == s) be true. S and I model sized_sentinel_for<S, I> only if If N is representable by iter_difference_t<I>, then s - i is well-defined and equals N. If −N is representable by iter_difference_t<I>, then i - s is well-defined and equals −N.

template<class S, class I>
 constexpr bool disable_sized_sentinel_for = false;

Remarks: Pursuant to [namespace.std], users may specialize disable_sized_sentinel_for for cv-unqualified non-array object types S and I if S and/or I is a program-defined type. Such specializations shall be usable in constant expressions ([expr.const]) and have type const bool.

template<class S, class I>
 constexpr bool disable_sized_sentinel_for = false;

[Note 1: disable_sized_sentinel_for allows use of sentinels and iterators with the library that satisfy but do not in fact model sized_sentinel_for. — end note]

template<class S, class I>
 constexpr bool disable_sized_sentinel_for = false;

[Example 1: The sized_sentinel_for concept is modeled by pairs of random_access_iterators ([iterator.concept.random.access]) and by counted iterators and their sentinels ([counted.iterator]). — end example]

The output_iterator concept defines requirements for a type that can be used to write values (from the requirement for indirectly_writable ([iterator.concept.writable])) and which can be both pre- and post-incremented. [Note 1: Output iterators are not required to model equality_comparable. — end note]

template<class I, class T>
 concept output_iterator =
 input_or_output_iterator<I> &&
 indirectly_writable<I, T> &&
 requires(I i, T&& t) {
 *i++ = std::forward<T>(t); // not required to be equality-preserving
 };

Let E be an expression such that decltype((E)) is T, and let i be a dereferenceable object of type I. I and T model output_iterator<I, T> only if *i++ = E; has effects equivalent to:

*i = E;
++i;

Recommended practice: The implementation of an algorithm on output iterators should never attempt to pass through the same iterator twice; such an algorithm should be a single-pass algorithm.

The bidirectional_iterator concept adds the ability to move an iterator backward as well as forward.

template<class I>
 concept bidirectional_iterator =
 forward_iterator<I> &&
 derived_from<ITER_CONCEPT(I), bidirectional_iterator_tag> &&
 requires(I i) {
 { --i } -> same_as<I&>;
 { i-- } -> same_as<I>;
 };

A bidirectional iterator r is decrementable if and only if there exists some q such that ++q == r. Decrementable iterators r shall be in the domain of the expressions --r and r--.

Let a and b be equal objects of type I. I models bidirectional_iterator only if: If a and b are decrementable, then all of the following are true: addressof(--a) == addressof(a) bool(a-- == b) after evaluating both a-- and --b, bool(a == b) is still true bool(++(--a) == b) If a and b are incrementable, then bool(--(++a) == b).

The random_access_iterator concept adds support for constant-time advancement with +=, +, -=, and -, as well as the computation of distance in constant time with -. Random access iterators also support array notation via subscripting.

template<class I>
 concept random_access_iterator =
 bidirectional_iterator<I> &&
 derived_from<ITER_CONCEPT(I), random_access_iterator_tag> &&
 totally_ordered<I> &&
 sized_sentinel_for<I, I> &&
 requires(I i, const I j, const iter_difference_t<I> n) {
 { i += n } -> same_as<I&>;
 { j + n } -> same_as<I>;
 { n + j } -> same_as<I>;
 { i -= n } -> same_as<I&>;
 { j - n } -> same_as<I>;
 { j[n] } -> same_as<iter_reference_t<I>>;
 };

Let a and b be valid iterators of type I such that b is reachable from a after n applications of ++a, let D be iter_difference_t<I>, and let n denote a value of type D. I models random_access_iterator only if (a += n) is equal to b. addressof(a += n) is equal to addressof(a). (a + n) is equal to (a += n). For any two positive values x and y of type D, if (a + D(x + y)) is valid, then (a + D(x + y)) is equal to ((a + x) + y). (a + D(0)) is equal to a. If (a + D(n - 1)) is valid, then (a + n) is equal to [](I c){ return ++c; }(a + D(n - 1)). (b += D(-n)) is equal to a. (b -= n) is equal to a. addressof(b -= n) is equal to addressof(b). (b - n) is equal to (b -= n). If b is dereferenceable, then a[n] is valid and is equal to *b. bool(a <= b) is true.

The contiguous_iterator concept provides a guarantee that the denoted elements are stored contiguously in memory.

template<class I>
 concept contiguous_iterator =
 random_access_iterator<I> &&
 derived_from<ITER_CONCEPT(I), contiguous_iterator_tag> &&
 is_lvalue_reference_v<iter_reference_t<I>> &&
 same_as<iter_value_t<I>, remove_cvref_t<iter_reference_t<I>>> &&
 requires(const I& i) {
 { to_address(i) } -> same_as<add_pointer_t<iter_reference_t<I>>>;
 };

Let a and b be dereferenceable iterators and c be a non-dereferenceable iterator of type I such that b is reachable from a and c is reachable from b, and let D be iter_difference_t<I>. The type I models contiguous_iterator only if to_address(a) == addressof(*a), to_address(b) == to_address(a) + D(b - a), to_address(c) == to_address(a) + D(c - a), ranges:: iter_move(a) has the same type, value category, and effects as std:: move(*a), and if ranges:: iter_swap(a, b) is well-formed, it has effects equivalent to ranges:: swap(*a, *b).

Class template projected is used to constrain algorithms that accept callable objects and projections ([defns.projection]). It combines an indirectly_readable type I and a callable object type Proj into a new indirectly_readable type whose reference type is the result of applying Proj to the iter_reference_t of I.

namespace std {
 template<indirectly_readable I, indirectly_regular_unary_invocable<I> Proj>
 struct projected {
 using value_type = remove_cvref_t<indirect_result_t<Proj&, I>>;
 indirect_result_t<Proj&, I> operator*() const; // not defined
 };
 template<weakly_incrementable I, class Proj>
 struct incrementable_traits<projected<I, Proj>> {
 using difference_type = iter_difference_t<I>;
 };
}

The indirectly_swappable concept specifies a swappable relationship between the values referenced by two indirectly_readable types.

template<class I1, class I2 = I1>
 concept indirectly_swappable =
 indirectly_readable<I1> && indirectly_readable<I2> &&
 requires(const I1 i1, const I2 i2) {
 ranges::iter_swap(i1, i1);
 ranges::iter_swap(i2, i2);
 ranges::iter_swap(i1, i2);
 ranges::iter_swap(i2, i1);
 };

It is often desirable for a function template specialization to find out what is the most specific category of its iterator argument, so that the function can select the most efficient algorithm at compile time. To facilitate this, the library introduces category tag classes which are used as compile time tags for algorithm selection. They are: output_iterator_tag, input_iterator_tag, forward_iterator_tag, bidirectional_iterator_tag, random_access_iterator_tag, and contiguous_iterator_tag. For every iterator of type I, iterator_traits<I>:: iterator_category shall be defined to be a category tag that describes the iterator's behavior. Additionally, iterator_traits<I>:: iterator_concept may be used to indicate conformance to the iterator concepts ([iterator.concepts]).

namespace std {
 struct output_iterator_tag { };
 struct input_iterator_tag { };
 struct forward_iterator_tag: public input_iterator_tag { };
 struct bidirectional_iterator_tag: public forward_iterator_tag { };
 struct random_access_iterator_tag: public bidirectional_iterator_tag { };
 struct contiguous_iterator_tag: public random_access_iterator_tag { };
}

[Example 1: A program-defined iterator BinaryTreeIterator can be included into the bidirectional iterator category by specializing the iterator_traits template:

template<class T> struct iterator_traits<BinaryTreeIterator<T>> {
 using iterator_category = bidirectional_iterator_tag;
 using difference_type = ptrdiff_t;
 using value_type = T;
 using pointer = T*;
 using reference = T&;
};

— end example]

[Example 2: If evolve() is well-defined for bidirectional iterators, but can be implemented more efficiently for random access iterators, then the implementation is as follows:

template<class BidirectionalIterator>
inline void
evolve(BidirectionalIterator first, BidirectionalIterator last) {
 evolve(first, last,
 typename iterator_traits<BidirectionalIterator>::iterator_category());
}
template<class BidirectionalIterator>
void evolve(BidirectionalIterator first, BidirectionalIterator last,
 bidirectional_iterator_tag) {
 // more generic, but less efficient algorithm
}
template<class RandomAccessIterator>
void evolve(RandomAccessIterator first, RandomAccessIterator last,
 random_access_iterator_tag) {
 // more efficient, but less generic algorithm
