ostream_iterator(ostream_type& s);

Effects: Initializes out_stream with addressof(s) and delim with nullptr.

ostream_iterator(ostream_type& s, const charT* delimiter);

Effects: Initializes out_stream with addressof(s) and delim with delimiter.

ostream_iterator& operator=(const T& value);

Effects: As if by:

*out_stream << value;
if (delim)
 *out_stream << delim;
return *this;

ostream_iterator& operator*();

Returns: *this.

ostream_iterator& operator++();
ostream_iterator& operator++(int);

Returns: *this.

The class template istreambuf_iterator defines an input iterator that reads successive characters from the streambuf for which it was constructed. operator* provides access to the current input character, if any. Each time operator++ is evaluated, the iterator advances to the next input character. If the end of stream is reached (streambuf_type:: sgetc() returns traits:: eof()), the iterator becomes equal to the end-of-stream iterator value. The default constructor istreambuf_iterator() and the constructor istreambuf_iterator(nullptr) both construct an end-of-stream iterator object suitable for use as an end-of-range. All specializations of istreambuf_iterator shall have a trivial copy constructor, a constexpr default constructor, and a trivial destructor.

The result of operator*() on an end-of-stream iterator is undefined. For any other iterator value a char_type value is returned. It is impossible to assign a character via an input iterator.

namespace std {
 template<class charT, class traits = char_traits<charT>>
 class istreambuf_iterator {
 public:
 using iterator_category = input_iterator_tag;
 using value_type = charT;
 using difference_type = typename traits::off_type;
 using pointer = unspecified;
 using reference = charT;
 using char_type = charT;
 using traits_type = traits;
 using int_type = typename traits::int_type;
 using streambuf_type = basic_streambuf<charT,traits>;
 using istream_type = basic_istream<charT,traits>;
 // [istreambuf.iterator.proxy], class istreambuf_iterator​::​proxy
 class proxy; // exposition only
 constexpr istreambuf_iterator() noexcept;
 constexpr istreambuf_iterator(default_sentinel_t) noexcept;
 istreambuf_iterator(const istreambuf_iterator&) noexcept = default;
 ~istreambuf_iterator() = default;
 istreambuf_iterator(istream_type& s) noexcept;
 istreambuf_iterator(streambuf_type* s) noexcept;
 istreambuf_iterator(const proxy& p) noexcept;
 istreambuf_iterator& operator=(const istreambuf_iterator&) noexcept = default;
 charT operator*() const;
 istreambuf_iterator& operator++();
 proxy operator++(int);
 bool equal(const istreambuf_iterator& b) const;
 friend bool operator==(const istreambuf_iterator& i, default_sentinel_t s);
 private:
 streambuf_type* sbuf_; // exposition only
 };
}

Class istreambuf_iterator<charT,traits>:: proxy is for exposition only. An implementation is permitted to provide equivalent functionality without providing a class with this name. Class istreambuf_iterator<charT, traits>:: proxy provides a temporary placeholder as the return value of the post-increment operator (operator++). It keeps the character pointed to by the previous value of the iterator for some possible future access to get the character.

namespace std {
 template<class charT, class traits>
 class istreambuf_iterator<charT, traits>::proxy { // exposition only
 charT keep_;
 basic_streambuf<charT,traits>* sbuf_;
 proxy(charT c, basic_streambuf<charT,traits>* sbuf)
 : keep_(c), sbuf_(sbuf) { }
 public:
 charT operator*() { return keep_; }
 };
}

constexpr istreambuf_iterator() noexcept;
constexpr istreambuf_iterator(default_sentinel_t) noexcept;

Effects: Initializes sbuf_ with nullptr.

